"""Tokenizer for minisql.

The lexer produces a flat list of :class:`Token` objects.  Every token carries
the absolute offsets of its first character and one past its last character so
that the parser can preserve the exact source text of expressions.
"""

from dataclasses import dataclass
from typing import Any, List

from .errors import QueryError


KEYWORDS = frozenset(
    {
        "SELECT",
        "DISTINCT",
        "FROM",
        "WHERE",
        "GROUP",
        "BY",
        "HAVING",
        "ORDER",
        "LIMIT",
        "OFFSET",
        "AS",
        "ASC",
        "DESC",
        "AND",
        "OR",
        "NOT",
        "IN",
        "BETWEEN",
        "LIKE",
        "IS",
        "NULL",
        "TRUE",
        "FALSE",
    }
)

# Longest first so that, for example, "<=" is never split into "<" and "=".
_MULTI_CHAR_OPS = ("||", "!=", "<>", "<=", ">=")

_SINGLE_CHAR_OPS = frozenset("(),;*+-/=<>")


@dataclass
class Token:
    kind: str  # "IDENT" | "STRING" | "NUMBER" | "KEYWORD" | "OP" | "EOF"
    value: Any
    start: int
    end: int
    quoted: bool = False


def _is_letter(ch: str) -> bool:
    return ("a" <= ch <= "z") or ("A" <= ch <= "Z")


def _is_digit(ch: str) -> bool:
    return "0" <= ch <= "9"


def _is_ident_start(ch: str) -> bool:
    return ch == "_" or _is_letter(ch)


def _is_ident_part(ch: str) -> bool:
    return ch == "_" or _is_letter(ch) or _is_digit(ch)


def _unterminated(what: str, start: int) -> QueryError:
    return QueryError("unterminated %s at position %d" % (what, start))


def tokenize(sql: str) -> List[Token]:
    """Split ``sql`` into tokens, always ending with an ``EOF`` token."""

    tokens: List[Token] = []
    i = 0
    n = len(sql)

    while i < n:
        ch = sql[i]

        if ch.isspace():
            i += 1
            continue

        start = i

        if _is_ident_start(ch):
            i += 1
            while i < n and _is_ident_part(sql[i]):
                i += 1
            word = sql[start:i]
            upper = word.upper()
            if upper in KEYWORDS:
                tokens.append(Token("KEYWORD", upper, start, i))
            else:
                tokens.append(Token("IDENT", word, start, i))
            continue

        if ch == "'":
            i += 1
            parts = []
            while True:
                if i >= n:
                    raise _unterminated("string literal", start)
                current = sql[i]
                if current == "'":
                    if i + 1 < n and sql[i + 1] == "'":
                        parts.append("'")
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    parts.append(current)
                    i += 1
            tokens.append(Token("STRING", "".join(parts), start, i))
            continue

        if ch == '"':
            i += 1
            parts = []
            while True:
                if i >= n:
                    raise _unterminated("quoted identifier", start)
                current = sql[i]
                if current == '"':
                    if i + 1 < n and sql[i + 1] == '"':
                        parts.append('"')
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    parts.append(current)
                    i += 1
            tokens.append(Token("IDENT", "".join(parts), start, i, quoted=True))
            continue

        if _is_digit(ch) or (ch == "." and i + 1 < n and _is_digit(sql[i + 1])):
            is_float = False
            if ch == ".":
                is_float = True
                i += 1
                while i < n and _is_digit(sql[i]):
                    i += 1
            else:
                while i < n and _is_digit(sql[i]):
                    i += 1
                if i < n and sql[i] == ".":
                    is_float = True
                    i += 1
                    while i < n and _is_digit(sql[i]):
                        i += 1
            raw = sql[start:i]
            value = float(raw) if is_float else int(raw)
            tokens.append(Token("NUMBER", value, start, i))
            continue

        matched = False
        for op in _MULTI_CHAR_OPS:
            if sql.startswith(op, i):
                tokens.append(Token("OP", op, start, i + len(op)))
                i += len(op)
                matched = True
                break
        if matched:
            continue

        if ch in _SINGLE_CHAR_OPS:
            tokens.append(Token("OP", ch, start, i + 1))
            i += 1
            continue

        raise QueryError("unexpected character %r at position %d" % (ch, start))

    tokens.append(Token("EOF", None, n, n))
    return tokens

"""Recursive-descent parser for minisql ``SELECT`` queries.

The parser turns the token stream from :mod:`minisql.lexer` into the AST types
in :mod:`minisql.ast`.  Expression nodes keep the exact source text that
produced them; output column names fall back to that text.
"""

from typing import List, Optional, Tuple

from . import ast
from .errors import QueryError
from .lexer import Token, tokenize


_COMPARE_OPS = frozenset({"=", "!=", "<>", "<", "<=", ">", ">="})

_ExprResult = Tuple[object, int, int]


class _Parser:
    def __init__(self, sql: str, tokens: List[Token]) -> None:
        self.sql = sql
        self.tokens = tokens
        self.index = 0

    # -- token helpers ---------------------------------------------------

    def _peek(self, offset: int = 0) -> Token:
        index = self.index + offset
        if index >= len(self.tokens):
            index = len(self.tokens) - 1
        return self.tokens[index]

    def _advance(self) -> Token:
        token = self.tokens[self.index]
        if token.kind != "EOF":
            self.index += 1
        return token

    def _matched_op(self, value: str) -> bool:
        token = self._peek()
        if token.kind == "OP" and token.value == value:
            self._advance()
            return True
        return False

    def _expect_op(self, value: str) -> Token:
        token = self._peek()
        if token.kind == "OP" and token.value == value:
            return self._advance()
        self._error("expected %r" % value)

    def _matched_keyword(self, value: str) -> bool:
        token = self._peek()
        if token.kind == "KEYWORD" and token.value == value:
            self._advance()
            return True
        return False

    def _expect_keyword(self, value: str) -> Token:
        token = self._peek()
        if token.kind == "KEYWORD" and token.value == value:
            return self._advance()
        self._error("expected %s" % value)

    def _expect_name(self, what: str) -> Token:
        token = self._peek()
        if token.kind == "IDENT":
            return self._advance()
        if token.kind == "KEYWORD":
            raise QueryError(
                "reserved keyword %s cannot be used as %s at position %d"
                % (token.value, what, token.start)
            )
        self._error("expected %s" % what)

    def _expect_uint(self, clause: str) -> int:
        token = self._peek()
        if token.kind != "NUMBER" or not isinstance(token.value, int):
            self._error("%s requires a non-negative integer" % clause)
        self._advance()
        return token.value

    def _source(self, start: int, end: int) -> str:
        return self.sql[start:end]

    def _error(self, message: str) -> None:
        token = self._peek()
        if token.kind == "EOF":
            raise QueryError("%s at end of query" % message)
        text = self.sql[token.start : token.end]
        raise QueryError(
            "%s at position %d near %r" % (message, token.start, text)
        )

    # -- statement -------------------------------------------------------

    def parse_query(self) -> ast.Query:
        self._expect_keyword("SELECT")
        distinct = self._matched_keyword("DISTINCT")

        star = False
        items: List[ast.SelectItem] = []
        if self._matched_op("*"):
            star = True
        else:
            items.append(self._select_item())
            while self._matched_op(","):
                items.append(self._select_item())

        self._expect_keyword("FROM")
        table = self._expect_name("a table name").value

        where = None
        if self._matched_keyword("WHERE"):
            where = self._expression()[0]

        group_by: List[object] = []
        if self._matched_keyword("GROUP"):
            self._expect_keyword("BY")
            group_by.append(self._expression()[0])
            while self._matched_op(","):
                group_by.append(self._expression()[0])

        having = None
        if self._matched_keyword("HAVING"):
            having = self._expression()[0]

        order_by: List[ast.OrderItem] = []
        if self._matched_keyword("ORDER"):
            self._expect_keyword("BY")
            order_by.append(self._order_item())
            while self._matched_op(","):
                order_by.append(self._order_item())

        limit: Optional[int] = None
        offset: Optional[int] = None
        if self._matched_keyword("LIMIT"):
            limit = self._expect_uint("LIMIT")
            if self._matched_keyword("OFFSET"):
                offset = self._expect_uint("OFFSET")

        self._matched_op(";")
        if self._peek().kind != "EOF":
            self._error("unexpected token")

        return ast.Query(
            distinct=distinct,
            star=star,
            items=items,
            table=table,
            where=where,
            group_by=group_by,
            having=having,
            order_by=order_by,
            limit=limit,
            offset=offset,
        )

    def _select_item(self) -> ast.SelectItem:
        expr = self._expression()[0]
        alias = None
        if self._matched_keyword("AS"):
            alias = self._expect_name("a column alias after AS").value
        elif self._peek().kind == "IDENT":
            # An unquoted (or quoted) name directly after an expression is an
            # implicit alias, as long as it is not a keyword.
            alias = self._advance().value
        return ast.SelectItem(expr=expr, alias=alias)

    def _order_item(self) -> ast.OrderItem:
        expr = self._expression()[0]
        desc = False
        if self._matched_keyword("ASC"):
            desc = False
        elif self._matched_keyword("DESC"):
            desc = True
        return ast.OrderItem(expr=expr, desc=desc)

    # -- expressions -----------------------------------------------------

    def _expression(self) -> _ExprResult:
        return self._or_expression()

    def _or_expression(self) -> _ExprResult:
        node, start, end = self._and_expression()
        while self._matched_keyword("OR"):
            right, _, right_end = self._and_expression()
            node = ast.Binary(self._source(start, right_end), "OR", node, right)
            end = right_end
        return node, start, end

    def _and_expression(self) -> _ExprResult:
        node, start, end = self._not_expression()
        while self._matched_keyword("AND"):
            right, _, right_end = self._not_expression()
            node = ast.Binary(self._source(start, right_end), "AND", node, right)
            end = right_end
        return node, start, end

    def _not_expression(self) -> _ExprResult:
        token = self._peek()
        if token.kind == "KEYWORD" and token.value == "NOT":
            self._advance()
            operand, _, end = self._not_expression()
            return (
                ast.Unary(self._source(token.start, end), "NOT", operand),
                token.start,
                end,
            )
        return self._comparison_expression()

    def _comparison_expression(self) -> _ExprResult:
        node, start, end = self._additive_expression()
        token = self._peek()

        if token.kind == "OP" and token.value in _COMPARE_OPS:
            self._advance()
            op = "!=" if token.value == "<>" else token.value
            right, _, right_end = self._additive_expression()
            return (
                ast.Compare(self._source(start, right_end), op, node, right),
                start,
                right_end,
            )

        if token.kind == "KEYWORD" and token.value == "IS":
            self._advance()
            negated = self._matched_keyword("NOT")
            self._expect_keyword("NULL")
            null_end = self.tokens[self.index - 1].end
            return (
                ast.IsNull(self._source(start, null_end), node, negated),
                start,
                null_end,
            )

        negated = False
        if token.kind == "KEYWORD" and token.value == "NOT":
            following = self._peek(1)
            if not (
                following.kind == "KEYWORD"
                and following.value in ("IN", "BETWEEN", "LIKE")
            ):
                self._error("expected IN, BETWEEN or LIKE after NOT")
            self._advance()
            negated = True
            token = self._peek()

        if token.kind == "KEYWORD" and token.value == "IN":
            self._advance()
            self._expect_op("(")
            if self._peek().kind == "OP" and self._peek().value == ")":
                self._error("IN requires at least one expression")
            items: List[object] = [self._expression()[0]]
            while self._matched_op(","):
                items.append(self._expression()[0])
            close = self._expect_op(")")
            return (
                ast.InList(
                    self._source(start, close.end), node, items, negated
                ),
                start,
                close.end,
            )

        if token.kind == "KEYWORD" and token.value == "BETWEEN":
            self._advance()
            low, _, _ = self._additive_expression()
            self._expect_keyword("AND")
            high, _, high_end = self._additive_expression()
            return (
                ast.Between(
                    self._source(start, high_end), node, low, high, negated
                ),
                start,
                high_end,
            )

        if token.kind == "KEYWORD" and token.value == "LIKE":
            self._advance()
            pattern, _, pattern_end = self._additive_expression()
            return (
                ast.Like(
                    self._source(start, pattern_end), node, pattern, negated
                ),
                start,
                pattern_end,
            )

        return node, start, end

    def _additive_expression(self) -> _ExprResult:
        node, start, end = self._multiplicative_expression()
        while True:
            token = self._peek()
            if token.kind != "OP" or token.value not in ("+", "-", "||"):
                break
            self._advance()
            right, _, right_end = self._multiplicative_expression()
            node = ast.Binary(
                self._source(start, right_end), token.value, node, right
            )
            end = right_end
        return node, start, end

    def _multiplicative_expression(self) -> _ExprResult:
        node, start, end = self._unary_expression()
        while True:
            token = self._peek()
            if token.kind != "OP" or token.value not in ("*", "/"):
                break
            self._advance()
            right, _, right_end = self._unary_expression()
            node = ast.Binary(
                self._source(start, right_end), token.value, node, right
            )
            end = right_end
        return node, start, end

    def _unary_expression(self) -> _ExprResult:
        token = self._peek()
        if token.kind == "OP" and token.value == "-":
            self._advance()
            operand, _, end = self._unary_expression()
            return (
                ast.Unary(self._source(token.start, end), "-", operand),
                token.start,
                end,
            )
        return self._primary()

    def _primary(self) -> _ExprResult:
        token = self._peek()

        if token.kind == "NUMBER":
            self._advance()
            return (
                ast.Literal(self._source(token.start, token.end), token.value),
                token.start,
                token.end,
            )

        if token.kind == "STRING":
            self._advance()
            return (
                ast.Literal(self._source(token.start, token.end), token.value),
                token.start,
                token.end,
            )

        if token.kind == "KEYWORD":
            if token.value == "NULL":
                self._advance()
                return (
                    ast.Literal(self._source(token.start, token.end), None),
                    token.start,
                    token.end,
                )
            if token.value in ("TRUE", "FALSE"):
                self._advance()
                return (
                    ast.Literal(
                        self._source(token.start, token.end),
                        token.value == "TRUE",
                    ),
                    token.start,
                    token.end,
                )
            self._error("unexpected keyword %s" % token.value)

        if token.kind == "IDENT":
            following = self._peek(1)
            if following.kind == "OP" and following.value == "(":
                return self._function()
            self._advance()
            return (
                ast.Column(self._source(token.start, token.end), token.value),
                token.start,
                token.end,
            )

        if token.kind == "OP" and token.value == "(":
            self._advance()
            operand, _, _ = self._expression()
            close = self._expect_op(")")
            return (
                ast.Paren(self._source(token.start, close.end), operand),
                token.start,
                close.end,
            )

        self._error("expected an expression")

    def _function(self) -> _ExprResult:
        name_token = self._advance()  # IDENT
        name = str(name_token.value).upper()
        self._expect_op("(")

        star_token = self._peek()
        if star_token.kind == "OP" and star_token.value == "*":
            self._advance()
            close = self._expect_op(")")
            return (
                ast.Func(
                    self._source(name_token.start, close.end),
                    name,
                    [],
                    True,
                ),
                name_token.start,
                close.end,
            )

        args: List[object] = []
        if not (self._peek().kind == "OP" and self._peek().value == ")"):
            args.append(self._expression()[0])
            while self._matched_op(","):
                args.append(self._expression()[0])
        close = self._expect_op(")")
        return (
            ast.Func(self._source(name_token.start, close.end), name, args),
            name_token.start,
            close.end,
        )


def parse(sql: str) -> ast.Query:
    """Parse ``sql`` into an :class:`minisql.ast.Query`."""

    return _Parser(sql, tokenize(sql)).parse_query()

